float sdRoundedBox( in vec2 p, in vec2 b, in vec4 r )
{
    r.xy = (p.x>0.0)?r.xy : r.zw;
    r.x  = (p.y>0.0)?r.x  : r.y;
    vec2 q = abs(p)-b+r.x;
    return min(max(q.x,q.y),0.0) + length(max(q,0.0)) - r.x;
}

float sdCircle( in vec2 p, in float r ) 
{
    return length(p)-r;
}

vec2 lerp (vec2 s, vec2 e, float t) {
    return s + e * t;
}


float easeOutQuart(float x) {
return 1. - pow(1. - x, 4.);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = vec4(1, 1, 1, 1);

    vec2 uv = (fragCoord * 2. - iResolution.xy) /iResolution.y;

    float blur = 1.5 / iResolution.y; 
    vec2 startCoord = vec2(.56, 0.);
    vec2 endCoord = -startCoord * 2.;
    vec2 animatedCoord = lerp(startCoord, endCoord, easeOutQuart(fract(iTime)));
    vec2 reversedAnimatedCoord = mod(iTime, 2.) <= 1. ? animatedCoord : -animatedCoord;

    float roundedBox = sdRoundedBox(uv, vec2(1.05, .5), vec4 (0.5, 0.5, 0.5, 0.5));
    float circle = sdCircle(uv + reversedAnimatedCoord, .4);

    roundedBox = smoothstep(-blur, blur, -roundedBox);
    circle = smoothstep(-blur, blur, -circle);

    float reversedTime = mod(iTime, 2.) < 1. ? clamp(0., 1., fract(iTime) / .2) : 1. - clamp(0., 1., fract(iTime) / .2);


    fragColor = mix(fragColor, mix(vec4(0.82, 0.84, 0.86, 1), vec4(0.23, 0.51, 0.96, 1), reversedTime), roundedBox);
    fragColor = mix(fragColor, mix(vec4(0.2, 0.25, 0.33, 1), vec4(1, 1, 1, 1), reversedTime), circle);
}
